// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.persona.emotionimport com.roshan.persona.persona.jit.GossipTriggerTypeimport java.time.LocalTimeimport java.util.concurrent.ConcurrentHashMap/** * NOUS — Cooldown Registry (Module 15 v3.0 — Step 15.3). * * Enforces two cooldown rules from strategy §7: * *  1. **The 24-Hour Gossip Rule** — a specific JIT gossip trigger (e.g., *     commenting on music choice or a missed call) can only fire **once per *     24 hours**. This prevents NOUS from repeating the same observation *     every time the user wakes it up. * *  2. **Silent Hours Override** — between 22:00 and 07:00, all proactive *     gossip triggers are disabled. NOUS only responds strictly to commands *     during silent hours. * * ## Design * * The registry tracks the last-fired timestamp for each [GossipTriggerType]. * When [canFire] is called, it checks: *  - Is it currently silent hours? If yes → false (gossip disabled). *  - Has 24 hours passed since the trigger last fired? If no → false. *  - Otherwise → true. * * ## Persistence * * For v1, the registry is in-memory (resets on app restart). This is * acceptable because: *  - Gossip is a "nice to have" — repeating once after restart isn't harmful. *  - Adding Room persistence in Step 15.4 or later is straightforward *    (same pattern as Module 10's PersistentUndoStack). * * @see <a href="docs/strategy/module-15-digital-soul-strategy.md">§7 Emotional Decay & Cooldowns</a> */class CooldownRegistry(    private val config: CooldownConfig = CooldownConfig(),) {    /** Maps each trigger type → last-fired epoch ms. */    private val lastFiredMs = ConcurrentHashMap<GossipTriggerType, Long>()    /**     * Check if a gossip trigger can fire right now.     *     * Returns false if:     *  - It's currently silent hours (22:00–07:00).     *  - The trigger fired within the last 24 hours.     *     * @param triggerType the type of gossip trigger to check.     * @param nowMs current epoch time in ms (injectable for testing).     * @param hourOfDay current hour 0-23 (injectable for testing).     * @return true if the trigger can fire.     */    fun canFire(        triggerType: GossipTriggerType,        nowMs: Long = System.currentTimeMillis(),        hourOfDay: Int = LocalTime.now().hour,    ): Boolean {        // 1. Silent hours override — no gossip 22:00-07:00.        if (isSilentHours(hourOfDay)) {            return false        }        // 2. 24-hour rule — each trigger fires max once per 24h.        val lastFired = lastFiredMs[triggerType]        if (lastFired != null) {            val elapsed = nowMs - lastFired            if (elapsed < config.gossipCooldownMs) {                return false            }        }        return true    }    /**     * Mark a trigger as fired. Called after the gossip is actually spoken.     *     * @param triggerType the trigger that fired.     * @param nowMs current epoch time (injectable for testing).     */    fun markFired(        triggerType: GossipTriggerType,        nowMs: Long = System.currentTimeMillis(),    ) {        lastFiredMs[triggerType] = nowMs    }    /**     * Time since a trigger last fired, or null if it never fired.     */    fun timeSinceLastFire(        triggerType: GossipTriggerType,        nowMs: Long = System.currentTimeMillis(),    ): Long? {        val lastFired = lastFiredMs[triggerType] ?: return null        return nowMs - lastFired    }    /**     * True if the given hour falls within silent hours (22:00–07:00).     *     * Silent hours wrap around midnight: 22, 23, 0, 1, 2, 3, 4, 5, 6 are silent.     * 7 AM (hour=7) is NOT silent — NOUS can gossip again.     */    fun isSilentHours(hourOfDay: Int): Boolean {        return hourOfDay in config.silentHoursStart..23 || hourOfDay < config.silentHoursEnd    }    /** Clear all cooldown records (for tests + Settings → Reset). */    fun clear() {        lastFiredMs.clear()    }    /** Number of triggers currently in cooldown (fired within last 24h). */    fun activeCooldownCount(nowMs: Long = System.currentTimeMillis()): Int {        return lastFiredMs.count { (_, lastFired) ->            nowMs - lastFired < config.gossipCooldownMs        }    }}// ──────────────────────────────────────────────────────────────────────────/** * Configuration for cooldown behavior. * * @param gossipCooldownMs how long before a gossip trigger can fire again *                          (default 24 hours per strategy §7). * @param silentHoursStart hour when silent hours begin (default 22 = 10 PM). * @param silentHoursEnd   hour when silent hours end (default 7 = 7 AM). */data class CooldownConfig(    val gossipCooldownMs: Long = DEFAULT_GOSSIP_COOLDOWN_MS,    val silentHoursStart: Int = DEFAULT_SILENT_START,    val silentHoursEnd: Int = DEFAULT_SILENT_END,) {    init {        require(gossipCooldownMs > 0) { "gossipCooldownMs must be positive" }        require(silentHoursStart in 0..23) { "silentHoursStart must be 0..23" }        require(silentHoursEnd in 0..23) { "silentHoursEnd must be 0..23" }        require(silentHoursStart != silentHoursEnd) { "silent hours start != end" }    }    companion object {        /** 24 hours in ms. */        const val DEFAULT_GOSSIP_COOLDOWN_MS = 24L * 60 * 60 * 1000        /** 10 PM — silent hours begin. */        const val DEFAULT_SILENT_START = 22        /** 7 AM — silent hours end. */        const val DEFAULT_SILENT_END = 7    }}